// Double-buffered DMA: fill one buffer while the peripheral drains the other
const N=32;
const src=Array.from({length:N},(_,i)=>i);
const b0=new Array(N),b1=new Array(N);
for(let i=0;i<N/2;i++){b0[i]=src[i];b1[i]=src[N/2+i];}
console.log('buf0 head:',b0.slice(0,4).join(','),'| buf1 head:',b1.slice(0,4).join(','),'| transferred:',N);

